//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}

#[test]
fn attribute_namespace_exact_units_distinct_replacement_null_index_alias_and_observation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument('urn:element','e:Root'),html=document.implementation.createHTMLDocument('owner'),svg=xml.createElementNS('http://www.w3.org/2000/svg','rect'),names=['\ud800','\udfff','\ufffd',null];for(var node of [document.createElement('span'),xml.documentElement,html.createElement('div'),svg]){var map=node.attributes,watch=new MutationObserver(function(){});watch.observe(node,{attributes:true,attributeOldValue:true});var attrs=[];for(var i=0;i<names.length;i++){var ns=names[i];node.setAttributeNS(ns,ns===null?'Case':'p:Case','value'+i);var attr=node.getAttributeNodeNS(ns,'Case');attrs.push(attr);if(attr.namespaceURI!==ns||attr.value!=='value'+i||node.getAttributeNS(ns,'Case')!==attr.value||map.getNamedItemNS(ns,'Case')!==attr)throw 'actual exact namespace lookup';}if(map.length!==4||attrs[0]===attrs[1]||attrs[0]===attrs[2]||attrs[3].namespaceURI!==null)throw 'distinct raw replacement and null identities';var records=watch.takeRecords();if(records.length!==4)throw 'exact namespace record count';for(var i=0;i<4;i++)if(records[i].attributeNamespace!==names[i]||records[i].attributeName!=='Case'||records[i].oldValue!==null)throw 'exact original namespace observation';node.setAttributeNS(names[0],'q:Case','changed');if(node.getAttributeNodeNS(names[0],'Case')!==attrs[0]||attrs[0].name!=='p:Case'||attrs[0].value!=='changed'||node.getAttributeNS(names[2],'Case')!=='value2')throw 'same prefix record and distinct replacement';attrs[0].value='alias';records=watch.takeRecords();if(records.length!==2||records[0].attributeNamespace!==names[0]||records[0].oldValue!=='value0'||records[1].attributeNamespace!==names[0]||records[1].oldValue!=='changed')throw 'canonical Attr setter exact namespace';node.removeAttributeNS(names[0],'Case');if(attrs[0].ownerElement!==null||attrs[0].namespaceURI!==names[0]||attrs[0].value!=='alias'||map.length!==3||node.getAttributeNodeNS(names[2],'Case')!==attrs[2])throw 'removal exact key and same identity';}
"#);
}
#[test]
fn attribute_namespace_factory_conversion_validation_clone_and_inert_attachment_are_exact(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,''),owner=document.implementation.createHTMLDocument('owner'),node=owner.createElement('span'),order='',raw='\ud800',attr=xml.createAttributeNS({toString:function(){order+='n';return raw;}},{toString:function(){order+='q';return 'p:Case';}});if(order!=='nq'||attr.namespaceURI!==raw||attr.ownerDocument!==xml||attr.prefix!=='p')throw 'converted exact factory namespace';attr.value='first';node.setAttributeNodeNS(attr);var clone=node.cloneNode(false),copied=clone.getAttributeNodeNS(raw,'Case');if(attr.ownerDocument!==owner||attr.ownerElement!==node||copied===attr||copied.namespaceURI!==raw||copied.name!=='p:Case'||copied.value!=='first')throw 'inert clone owns exact namespace';var changed=owner.createAttributeNS(raw,'q:Case');changed.value='next';if(node.setAttributeNodeNS(changed)!==attr||changed.namespaceURI!==raw||attr.namespaceURI!==raw||attr.ownerElement!==null||node.getAttributeNodeNS(raw,'Case')!==changed)throw 'actual expanded-name identity replacement';
var caught=false;order='';try{xml.createAttributeNS({toString:function(){order+='n';return raw;}},{toString:function(){order+='q';return 'xml:Case';}});}catch(e){caught=e instanceof DOMException&&e.name==='NamespaceError';}if(!caught||order!=='nq')throw 'raw URI is distinct from XML namespace after ordered conversion';caught=false;try{node.setAttributeNS(raw,'xmlns:Case','bad');}catch(e){caught=e instanceof DOMException&&e.name==='NamespaceError';}if(!caught||node.attributes.length!==1||changed.ownerElement!==node)throw 'raw URI is not namespace declaration authority';
"#);
}

#[test]
fn attribute_namespace_raw_factory_retained_copy_refusal_and_origin_revalidation_publish_no_prefix(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var xml=document.implementation.createDocument(null,'Root');");let before=(doc.nodes.len(),page.state.retained,page.state.attributes.len(),page.state.dom_commits);let limit=page.state.retained_limit;page.state.retained_limit=page.state.retained;
 assert_eq!(page.console_eval(&mut doc,&mut forms,"xml.createAttributeNS('\\ud800','p:Units');").errors,1);assert_eq!((doc.nodes.len(),page.state.retained,page.state.attributes.len(),page.state.dom_commits),before);page.state.retained_limit=limit;
 run(&mut doc,&mut forms,&mut page,r#"var raw='\ud800',calls=0,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Document.prototype.createAttributeNS,namespace={toString:function(){calls++;return raw;}},first=saved.call(xml,namespace,'p:Units');if(first.namespaceURI!==raw||calls!==1||Object.getPrototypeOf(saved)!==w.Function.prototype)throw 'actual raw child realm factory';"#);page.set_location(&crate::navigation::address("https://other-raw-namespace.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(xml,namespace,'p:Units');").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==1||first.namespaceURI!==raw)throw 'origin guard before namespace conversion';");
}
